import {defaults,exercises,dayKey,validSettings,signature,plan,proposal,eligible,fresh} from './model.js';
const $=s=>document.querySelector(s), app=$('#app'),KEY='rehab-johan-v1';let state=fresh(),session=null,timer=null,deadline=0,remaining=0,running=false,audio=null,lock=null,current='home',cancelPrompt=false,unreadStorage=null;
function notice(t){$('#notice').hidden=!t;$('#notice').textContent=t}
try{const raw=localStorage.getItem(KEY);unreadStorage=raw;if(raw){const v=JSON.parse(raw);if(v.version!==1||!Array.isArray(v.history)||v.history.some(x=>!x||typeof x.at!=='string'||typeof x.day!=='string'))throw Error();state={...fresh(),...v,settings:validSettings(v.settings)}}unreadStorage=null;}catch{notice('Tidigare uppgifter kunde inte läsas. Ingenting skrivs över automatiskt. Exportera det som går att återställa eller ladda om sidan innan du sparar nya uppgifter.');}
function save(){if(unreadStorage!==null){notice('Tidigare lagring kunde inte läsas. Exportera originalet via knappen nedan innan du ersätter det.');showRecovery();return false}try{localStorage.setItem(KEY,JSON.stringify(state));notice('');return true}catch{notice('Det gick inte att spara på enheten. Behåll sidan öppen och exportera historiken under Framsteg.');return false}}
function showRecovery(){const box=$('#notice');if(!box.querySelector('button')){const b=document.createElement('button');b.textContent='Exportera original och använd den nya historiken';b.onclick=()=>{const a=document.createElement('a'),u=URL.createObjectURL(new Blob([unreadStorage],{type:'application/json'}));a.href=u;a.download='rehab-original.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);unreadStorage=null;save()};box.append(document.createElement('br'),b)}}
function esc(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function button(id,text,cls='secondary'){return `<button id="${id}" class="${cls}">${text}</button>`}
function heading(k,t,p=''){return `<p class="eyebrow">${k}</p><h1 tabindex="-1">${t}</h1>${p?`<p class="lead">${p}</p>`:''}`}
function dateLabel(d){return new Date(d+'T12:00:00').toLocaleDateString('sv-SE',{day:'numeric',month:'short'})}
function dayDone(){return state.history.some(x=>x.day===dayKey())}
function pending(){return state.history.filter(x=>x.day<dayKey()&&!x.next)}
function week(){let h='';for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=dayKey(d);h+=`<div class="day ${state.history.some(x=>x.day===key)?'done':''} ${i===0?'today':''}">${d.toLocaleDateString('sv-SE',{weekday:'short'})}<b>${state.history.some(x=>x.day===key)?'✓':d.getDate()}</b></div>`}return `<div class="week" aria-label="De senaste sju dagarna">${h}</div>`}
function home(){const s=state.settings,p=plan(s),stretch=p.filter(x=>x.kind==='stretch').reduce((n,x)=>n+x.seconds,0),heel=3*s.reps*(1+s.lower);return heading('Ett pass om dagen',dayDone()?'Dagens pass är klart.':'En stund för din återhämtning.','Dina hemövningar, lugnt och steg för steg.')+`<section class="card hero"><div class="row"><span class="pill">${dayDone()?'✓ Genomfört i dag':'Ditt nästa pass'}</span><span class="note">8 övningar</span></div><div class="metrics"><div><strong>${s.stretch} s</strong><span>stretch</span></div><div><strong>3 × ${s.reps}</strong><span>styrkeövningar</span></div><div><strong>${Math.ceil((stretch+heel)/60)}+ min</strong><span>plus knäböj och pauser</span></div></div>${button('start',dayDone()?'Passet sparat i dag':'Starta mitt pass','primary')}<p class="note divider">Ta fram en boll, en stadig stol och ett trappsteg. Du startar själv varje ny övning och sida.</p></section>${pending().length?`<section class="card"><p class="eyebrow">Följ upp</p><h2>Hur kändes kroppen dagen efter?</h2><p class="muted">Svara för tidigare pass innan du tar ställning till en ökning.</p>${button('follow','Följ upp senaste pass')}</section>`:''}${eligible(state)?`<section class="card"><p class="eyebrow">Du bestämmer</p><h2>Vill du ta nästa steg?</h2><p>Tre pass på olika dagar har känts bra, även dagen efter.</p><p><strong>${proposal(s).label}</strong></p><p class="note">Detta är appens förslag, inte en progressionsplan från fysioterapeuten.</p><div class="actions">${button('increase','Godkänn ökningen','primary')}${button('stay','Behåll nivån')}</div></section>`:''}<section class="card"><div class="row"><h2>Din vecka</h2><a href="#progress" class="note">Visa framsteg →</a></div>${week()}</section><p class="note">Övningar och intervall från ditt Physiotools-program. Antalet pass är ditt val. Öka en sak i taget och stäm av progressionen med fysioterapeuten.</p>`}
function program(){return heading('Ditt upplägg','Åtta övningar. Ett pass.','Öppna en övning för att se bild och instruktion.')+`<p class="note">Bilder och instruktioner: ditt Physiotools-program. Varje pass innehåller alla åtta övningar. För ensidiga övningar utom vadstretch med rakt ben är båda sidor ett val i appen; PDF:en anger inte sida.</p>`+exercises.map((e,i)=>`<details><summary><span class="num">${i+1}</span>${e.name}</summary><div class="instruction"><img class="exercise-image" src="assets/exercise-${e.img}.png" alt="${e.name}"><div><p>${e.text}</p><p class="note">${e.dose}</p>${e.video?`<a class="button" href="${esc(e.video)}" target="_blank" rel="noopener">Visa originalvideo ↗</a>`:''}</div></div></details>`).join('')+`<section class="card"><h2>Progression i din takt</h2><p>Börja med 45 sekunder stretch och 3 × 10 repetitioner. Appen erbjuder en ökning efter tre pass på olika dagar på samma nivå, om du markerat att både passet och dagen efter kändes bra.</p><p>Först ökas stretchtiden med 5 sekunder till högst 60. Sedan ökas repetitionerna en i taget till 15, och sist sänkningen i tåhävningarna till högst 5 sekunder. Du godkänner varje ändring.</p><p class="note">Regeln är ett appupplägg som behöver stämmas av med fysioterapeuten. Missade dagar ger ingen ökning. Avbrutna pass räknas inte. Vila mellan set och sidval är appinställningar, inte en angiven ordination.</p></section>`}
function progress(){const weekKeys=[];for(let i=0;i<7;i++){let d=new Date();d.setDate(d.getDate()-i);weekKeys.push(dayKey(d))}return heading('Översikt','Din träning hittills.')+`<div class="card"><div class="metrics"><div><strong>${state.history.length}</strong><span>genomförda pass</span></div><div><strong>${state.history.filter(x=>weekKeys.includes(x.day)).length} / 7</strong><span>senaste veckan</span></div><div><strong>${state.settings.stretch} s</strong><span>aktuell stretch</span></div></div>${week()}</div><h2>Passhistorik</h2>${state.history.length?state.history.slice().reverse().map(x=>`<div class="history"><div><strong>${dateLabel(x.day)}</strong><small>${esc(x.settings.stretch)} s · 3 × ${esc(x.settings.reps)}</small></div><div>${x.feel==='good'?'Kändes bra':x.feel==='hard'?'Ansträngande':'Besvär'}<small>${x.next?(x.next==='good'?'Bra dagen efter':x.next==='hard'?'Trött dagen efter':'Besvär dagen efter'):'Uppföljning återstår'}</small></div></div>`).join(''):'<p class="muted">Ditt första genomförda pass visas här.</p>'}<div class="actions">${button('export','Exportera historik')}</div><p class="note">Sparas enbart i den här webbläsaren. Exportera en säkerhetskopia om du vill behålla dina uppgifter.</p>`}
function settings(){const s=state.settings;return heading('Ditt upplägg','Gör det till ditt.','Justera inom intervallen från ditt program.')+`<form id="settings-form" class="card">${[['stretch','Stretchtid (sekunder)',45,60],['reps','Repetitioner per set · 3 set',10,15],['lower','Sänkning i tåhävning (sekunder)',3,5],['rounds','Omgångar där PDF:en anger 1–2',1,2],['rest','Vila mellan set (sekunder)',0,120]].map(([k,l,min,max])=>`<label><span>${l}</span><input name="${k}" type="number" min="${min}" max="${max}" step="1" value="${s[k]}" required></label>`).join('')}<label class="check"><span>Ljud som stöd</span><input name="sound" type="checkbox" ${s.sound?'checked':''}></label><label class="check"><span>Båda sidor för ensidiga övningar</span><input name="both" type="checkbox" ${s.both?'checked':''}></label><p class="note">Vadstretch med rakt ben görs alltid på båda sidor enligt PDF:en. Sidval för övriga övningar och 30 sekunders standardvila är appval; anpassa efter fysioterapeutens råd.</p>${button('save-settings','Spara mitt upplägg','primary')}<p id="settings-saved" role="status" class="note"></p></form><section class="card"><h2>På mobilen</h2><p>Lägg sidan på hemskärmen via webbläsarens meny. Håll appen synlig under passet. Om du lämnar den pausas timern och du fortsätter själv när du kommer tillbaka.</p><p class="note">Ljud kräver att du startar eller fortsätter passet. Telefonens volym styr nivån. Vibration stöds inte på alla telefoner.</p></section>`}
function render(view=location.hash.slice(1)||'home',focus=false){if(completed&&!session)view='complete';if(view==='complete'&&!completed)view='home';if(session){renderSession();return}current=['home','program','progress','settings','follow','complete'].includes(view)?view:'home';$('#nav').hidden=false;app.innerHTML=current==='program'?program():current==='progress'?progress():current==='settings'?settings():current==='follow'?follow():current==='complete'?complete():home();$('#nav').querySelectorAll('a').forEach(a=>{if(a.hash==='#'+current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});bind();if(focus)app.querySelector('h1')?.focus()}
function follow(){const x=pending().at(-1);return heading('Uppföljning',x?'Hur kändes dagen efter?':'Alla pass är uppföljda.',x?`Passet ${dateLabel(x.day)}. Ditt svar hjälper dig att bedöma nästa steg.`:'')+(x?choices('next'):'<a href="#home" class="button">Till hem</a>')}
function choices(prefix){return `<div class="choices">${button(prefix+'-good','Kändes bra')}${button(prefix+'-hard','Trött eller ansträngd')}${button(prefix+'-pain','Besvär eller mer ont')}</div><p class="note divider">Vid besvär föreslår appen ingen ökning. Anpassa träningen och kontakta din fysioterapeut om du är osäker på hur du ska fortsätta.</p>`}
let completed=null;
function complete(){return heading('Ett pass genomfört','Passet är klart.','Hur kändes det?')+`<section class="card"><p>Du genomförde alla åtta övningar. Välj ett svar för att spara passet.</p>${choices('feel')}</section>`}
function bind(){function on(id,fn){const el=document.getElementById(id);if(el)el.onclick=fn}on('start',()=>{if(dayDone())return;start()});if(dayDone()&&$('#start'))$('#start').disabled=true;on('export',()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='rehab-historik-'+dayKey()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});on('follow',()=>{location.hash='follow'});on('increase',()=>{if(!eligible(state))return;const p=proposal(state.settings);state.settings[p.key]=p.value;state.progressAfter=new Date().toISOString();save();render('home')});on('stay',()=>{state.progressAfter=new Date().toISOString();save();render('home')});for(const v of ['good','hard','pain']){on('next-'+v,()=>{const x=pending().at(-1);if(x){x.next=v;if(v!=='good')state.progressAfter=new Date().toISOString();save()}render('follow')});on('feel-'+v,()=>{if(!completed)return;if(!state.history.some(x=>x.id===completed.id)){state.history.push({...completed,feel:v});if(v!=='good')state.progressAfter=new Date().toISOString();save()}completed=null;location.hash='home';render('home')})}const f=$('#settings-form');if(f)f.onsubmit=e=>{e.preventDefault();const d=new FormData(f),s={...defaults};for(const k of ['stretch','reps','lower','rounds','rest'])s[k]=Number(d.get(k));s.sound=d.has('sound');s.both=d.has('both');state.settings=validSettings(s);state.progressAfter=new Date().toISOString();if(save())$('#settings-saved').textContent='Ditt upplägg är sparat.'}}
async function initAudio(){if(!state.settings.sound)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();await audio.resume()}catch{notice('Ljud kunde inte startas. Timern fungerar utan ljud.')}}
function beep(){if(!state.settings.sound||!audio||audio.state!=='running')return;try{const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=620;g.gain.setValueAtTime(.08,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.15);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.16)}catch{}}
async function wake(){try{lock=await navigator.wakeLock?.request('screen')}catch{}}
function release(){lock?.release().catch(()=>{});lock=null}
function start(){session={settings:{...state.settings},steps:plan(state.settings),index:0,rep:1,phase:'ready',started:new Date().toISOString()};cancelPrompt=false;renderSession();window.scrollTo(0,0)}
function step(){return session.steps[session.index]}
function renderSession(){const t=step(),e=exercises[t.ei];$('#nav').hidden=true;const phase={ready:'Gör dig redo',up:'Upp',down:'Sänk långsamt',hold:'Håll kvar',manual:'Ditt eget tempo',rest:'Vila',done:'Bra, den delen är klar'}[session.phase];app.innerHTML=heading(`Övning ${t.ei+1} av 8`,e.name)+`<div class="row wrap"><span class="pill">${t.side?t.side+' · ':''}${t.kind==='stretch'?`Omgång ${t.set} av ${t.sets}`:`Set ${t.set} av ${t.sets}`}</span><span class="note">${t.kind==='stretch'?t.seconds+' sekunder':t.reps+' repetitioner'}</span></div><div class="progressbar" aria-label="Passets framsteg"><i style="width:${100*session.index/session.steps.length}%"></i></div><div class="instruction"><img class="exercise-image" src="assets/exercise-${e.img}.png" alt="${e.name}"><div><p>${e.text}</p>${e.video?`<a href="${esc(e.video)}" target="_blank" rel="noopener">Visa video ↗</a>`:''}</div></div><section class="timer"><p class="phase" id="phase" role="status">${phase}</p><div class="ring"><div class="ring-inner" role="timer" aria-live="off"><strong id="digits">${session.phase==='ready'?(t.kind==='stretch'?t.seconds:t.reps):t.kind==='squat'&&session.phase==='manual'?session.rep:'—'}</strong><span id="timer-unit">${t.kind==='squat'?'repetitioner':session.phase==='ready'&&t.kind==='heel'?'repetitioner':'sekunder'}</span></div></div><p class="muted" id="count">${t.kind==='stretch'?'Andas lugnt':`Repetition ${session.rep} av ${t.reps}`}</p></section><div id="session-controls">${controls()}</div><div class="actions">${button('sound',session.settings.sound?'Ljud på':'Ljud av')}${button('cancel','Avbryt pass','danger')}</div><div id="cancel-prompt">${cancelPrompt?`<div class="card"><p>Avbryta passet? Det räknas då inte som genomfört.</p><div class="actions">${button('confirm-cancel','Ja, avbryt','danger')}${button('keep','Stanna kvar')}</div></div>`:''}</div>`;bindSession();paint()}
function controls(){if(session.phase==='ready')return button('go',session.index?'Starta nästa del':'Starta övningen','primary');if(session.phase==='done')return button('next',session.index===session.steps.length-1?'Avsluta och följ upp':'Fortsätt →','primary');if(session.phase==='manual')return `${button('rep',`Klar med repetition ${session.rep}`,'primary')}<p class="note">Tryck efter varje knäböj. Ingen tid är föreskriven i PDF:en.</p>`;return button('pause',running?'Pausa':'Fortsätt','primary')}
function bindSession(){const on=(id,f)=>{if($('#'+id))$('#'+id).onclick=f};on('go',()=>{initAudio();wake();if(step().kind==='squat'){session.phase='manual';renderSession()}else begin(step().kind==='heel'?'up':'hold',step().kind==='heel'?1:step().seconds)});on('pause',()=>{if(running)pause();else{initAudio();wake();resume()}});on('rep',()=>{if(session.rep<step().reps){session.rep++;renderSession()}else finishPart()});on('next',nextPart);on('sound',()=>{session.settings.sound=!session.settings.sound;state.settings.sound=session.settings.sound;save();initAudio();renderSession()});on('cancel',()=>{pause();cancelPrompt=true;renderSession()});on('keep',()=>{cancelPrompt=false;renderSession()});on('confirm-cancel',()=>{clearInterval(timer);running=false;session=null;release();render('home')})}
let duration=0,lastSecond=-1;
function begin(phase,seconds){session.phase=phase;duration=seconds;remaining=seconds*1000;resume()}
function resume(){deadline=performance.now()+remaining;running=true;lastSecond=-1;clearInterval(timer);timer=setInterval(tick,60);renderSession();beep()}
function pause(){if(running){remaining=Math.max(0,deadline-performance.now());running=false}clearInterval(timer);release();if(session)renderSession()}
function paint(){if(!session)return;const timed=['up','down','hold','rest'].includes(session.phase);if(timed){const secs=Math.ceil(Math.max(0,running?deadline-performance.now():remaining)/1000);$('#digits').textContent=secs;$('#timer-unit').textContent='sekunder';$('.ring').style.setProperty('--sweep',Math.min(100,100*(1-(running?deadline-performance.now():remaining)/(duration*1000)))+'%');if(secs!==lastSecond){lastSecond=secs;if(running&&session.phase!=='rest'&&secs>0&&session.phase!=='hold')beep()}}}
function tick(){if(!session||!running)return;if(performance.now()>=deadline){running=false;clearInterval(timer);remaining=0;if(session.phase==='up')begin('down',step().lower);else if(session.phase==='down'&&session.rep<step().reps){session.rep++;begin('up',1)}else if(session.phase==='rest'){session.phase='ready';renderSession()}else finishPart()}else paint()}
function finishPart(){running=false;clearInterval(timer);session.phase='done';release();beep();renderSession()}
function nextPart(){const old=step();session.index++;session.rep=1;if(session.index>=session.steps.length){completed={id:crypto.randomUUID(),at:new Date().toISOString(),day:dayKey(),settings:session.settings,signature:signature(session.settings),next:null};session=null;release();location.hash='complete';render('complete');return}if(step().ei===old.ei&&step().set!==old.set&&session.settings.rest>0)begin('rest',session.settings.rest);else{session.phase='ready';renderSession();window.scrollTo(0,0)}}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&session&&running){pause();notice('Passet pausades när du lämnade appen. Fortsätt när du är redo.')}});
window.addEventListener('pagehide',()=>{if(session&&running)pause()});window.addEventListener('beforeunload',e=>{if(session||completed){e.preventDefault();e.returnValue=''}});
window.addEventListener('hashchange',()=>{if(!session)render(undefined,true)});
// Keep the completion questionnaire until it is answered, even if navigation changes.
window.addEventListener('hashchange',()=>{if(completed&&!session)render('complete')});
render();if(unreadStorage!==null)showRecovery();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
